/* op 35: column_chunk. shim, @error(status), detail. G1: stmt u32 @0, col i32 @4, offset u64 @8,
 * dst.cap u32 @16 (20). G2: ret i32 @0 (4). V2: dst. RESP_BOUND 1048595. */
static hqqrpc_status op_column_chunk(hqqrpc_call *c) {
    hqqrpc_session *s = c->session;
    hqqrpc_rd r;
    const uint8_t *g;
    uint8_t *o, *v;
    hqqrpc_status st;
    hqqrpc_wr w;
    uint32_t h_stmt;
    void *p;
    int32_t col;
    uint64_t offset;
    uint32_t cap;
    size_t n = 0;
    int32_t ret;
    uint64_t bound;
    uint8_t flags = 0;
    uint32_t dstn;

    hqqrpc_rd_init(&r, c);
    if ((st = hqqrpc_rd_take(&r, 8, 20, &g)) != HQQRPC_OK || (st = hqqrpc_rd_end(&r)) != HQQRPC_OK)
        return st;
    memcpy(&h_stmt, g + 0, 4);
    memcpy(&col, g + 4, 4);
    memcpy(&offset, g + 8, 8);
    memcpy(&cap, g + 16, 4);
    if (cap > 1048576)
        return HQQRPC_E_LIMIT;
    bound = (uint64_t)8 + HQQRPC_VAR_SLACK + cap;
    if (bound < (uint64_t)8 + HQQRPC_DETAIL_RESERVE)
        bound = (uint64_t)8 + HQQRPC_DETAIL_RESERVE;
    if ((st = hqqrpc_handle_get(s, h_stmt, SQLITE3_H_STMT, 0, &p)) != HQQRPC_OK ||
        (st = hqqrpc_resp_begin(c, bound, &w)) != HQQRPC_OK)
        return st;
    o = hqqrpc_wr_fixed(&w, 4, 4);
    v = hqqrpc_wr_span(&w, 1, (size_t)8 + cap);
    if (o == NULL || v == NULL) {
        return w.err;
    }
    ret = column_chunk((sqlite3_stmt *)p, col, offset, (void *)(v + 8), (size_t)cap, &n);
    memcpy(o, &ret, 4);
    if (ret == 0) {
        if ((uint64_t)n > cap)
            return HQQRPC_E_INTERNAL;
        dstn = (uint32_t)n;
        memset(v, 0, 4);
        memcpy(v + 4, &dstn, 4);
        if (hqqrpc_wr_advance(&w, (size_t)8 + dstn) != HQQRPC_OK)
            return w.err;
    } else {
        flags = HQQRPC_F_FAIL | hqqrpc_wr_put_detail(&w, stmt_errmsg((sqlite3_stmt *)p));
    }
    return hqqrpc_resp_commit(c, &w, flags);
}

static hqqrpc_status sqlite3_dispatch(hqqrpc_call *c) {
    switch (c->op) {
    case 1: return op_sqlite3_open_v2(c);
    case 2: return op_sqlite3_close(c);
    case 3: return op_sqlite3_busy_timeout(c);
    case 4: return op_sqlite3_changes64(c);
    case 5: return op_sqlite3_last_insert_rowid(c);
    case 6: return op_sqlite3_get_autocommit(c);
    case 7: return op_sqlite3_errcode(c);
    case 8: return op_sqlite3_extended_errcode(c);
    case 9: return op_sqlite3_errmsg(c);
    case 10: return op_sqlite3_libversion_number(c);
    case 11: return op_sqlite3_libversion(c);
    case 12: return op_sqlite3_prepare_v2(c);
    case 13: return op_prepare_one(c);
    case 14: return op_sqlite3_step(c);
    case 15: return op_sqlite3_reset(c);
    case 16: return op_sqlite3_finalize(c);
    case 17: return op_sqlite3_clear_bindings(c);
    case 18: return op_sqlite3_stmt_readonly(c);
    case 19: return op_sqlite3_bind_parameter_count(c);
    case 20: return op_sqlite3_bind_parameter_index(c);
    case 21: return op_sqlite3_bind_parameter_name(c);
    case 22: return op_sqlite3_bind_int64(c);
    case 23: return op_sqlite3_bind_double(c);
    case 24: return op_sqlite3_bind_null(c);
    case 25: return op_sqlite3_bind_zeroblob64(c);
    case 26: return op_bind_text(c);
    case 27: return op_bind_blob(c);
    case 28: return op_bind_values(c);
    case 29: return op_exec_stmt(c);
    case 30: return op_sqlite3_column_count(c);
    case 31: return op_sqlite3_column_name(c);
    case 32: return op_sqlite3_column_decltype(c);
    case 33: return op_stmt_info(c);
    case 34: return op_fetch_rows(c);
    case 35: return op_column_chunk(c);
    default: return HQQRPC_E_UNKNOWN_OP; /* default deny (7.1) */
    }
}

