/* Writers for union Value: tag u32 (aligned 4), then the payload. */
hqqrpc_status sqlite3_Value_put_Int(hqqrpc_wr *w, int64_t v) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 1u);
    return st != HQQRPC_OK ? st : hqqrpc_wr_put_u64(w, (uint64_t)v);
}
hqqrpc_status sqlite3_Value_put_Float(hqqrpc_wr *w, double v) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 2u);
    uint8_t *o;

    if (st != HQQRPC_OK)
        return st;
    if ((o = hqqrpc_wr_fixed(w, 8, 8)) == NULL)
        return w->err;
    memcpy(o, &v, 8);
    return HQQRPC_OK;
}
hqqrpc_status sqlite3_Value_put_Text(hqqrpc_wr *w, const char *s, uint32_t n) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 3u);
    return st != HQQRPC_OK ? st : hqqrpc_wr_put_str(w, s, n, UINT32_MAX);
}
hqqrpc_status sqlite3_Value_put_Blob(hqqrpc_wr *w, const void *p, uint32_t n) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 4u);
    return st != HQQRPC_OK ? st : hqqrpc_wr_put_bytes(w, p, n, UINT32_MAX);
}
hqqrpc_status sqlite3_Value_put_Null(hqqrpc_wr *w) { return hqqrpc_wr_put_u32(w, 5u); }
hqqrpc_status sqlite3_Value_put_TextRaw(hqqrpc_wr *w, const void *p, uint32_t n) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 6u);
    return st != HQQRPC_OK ? st : hqqrpc_wr_put_bytes(w, p, n, UINT32_MAX);
}
hqqrpc_status sqlite3_Value_put_BigText(hqqrpc_wr *w, uint64_t v) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 7u);
    return st != HQQRPC_OK ? st : hqqrpc_wr_put_u64(w, (uint64_t)v);
}
hqqrpc_status sqlite3_Value_put_BigBlob(hqqrpc_wr *w, uint64_t v) {
    hqqrpc_status st = hqqrpc_wr_put_u32(w, 8u);
    return st != HQQRPC_OK ? st : hqqrpc_wr_put_u64(w, (uint64_t)v);
}
